$f=fopen($out.'/inventory.csv','w');$columns=['id','name_registered','country','association','confederation','region','type','official_level','simulation_tier','scope','edition','participant_count','upper','lower','status','rules_version','reference_origin','present_in_cached_hub','official_rules_validation','calendar_model'];fputcsv($f,$columns,',','"','');foreach($rows as $r)fputcsv($f,array_map(fn($k)=>is_bool($r[$k])?($r[$k]?'true':'false'):$r[$k],$columns),',','"','');fclose($f);
